function UIFishPoolStoreBackPackGoodsNode:Refresh(data, cb, fishPlaceId)
    if not data then
        return
    end
    if not self._goodNodeScr then 
        self._goodNodeScr = CfUtils.GetLuaScr(self.GoodNode, "Game.Behaviours.GoodNodeMB")
    end

    self._curFishingPlaceId = fishPlaceId
    self._data = data
    self._cb = cb
    self:FillSelf()
end

function UIFishPoolStoreBackPackGoodsNode:RefreshEquipInfo()
