        return
    end
    local type = GoodsUtils.GetIdType(self._data.id)
    local equipId = FishingUtils.GetFishingEquipIdByType(type, self._curFishingPlaceId)
    KTool.SetActive(self.CurrentEquip, checkNumber(equipId) == checkNumber(self._data.id))
end

