function UIFishPoolStoreBackPackGoodsNode:IsHaveGoods()
    local isHave = false
    local type = GoodsUtils.GetIdType(self._data.id)
    if type == Constants.IDType.GoodsReel or type == Constants.IDType.GoodsFishingRod then
        local dojo = FishingUtils.GetFishingGoodsDojo(self._data.id)
        if dojo then
            isHave = true
        else
        end
    else
        local dojo = FishingUtils.GetFishingGoodsDojo(self._data.id)
        if dojo then
            isHave = true
        else
        end
    end
    return isHave
end

